package main

import "os"

func processOne(name string) error {
	f, err := os.Open(name)
	if err != nil {
		return err
	}
	defer f.Close() // сработает при выходе из processOne — на каждой итерации
	_ = f
	return nil
}

func processAll(files []string) error {
	for _, name := range files {
		if err := processOne(name); err != nil {
			return err
		}
	}
	return nil
}

func main() {
	_ = processAll([]string{"a.txt", "b.txt"})
}

